functions {
    //Compute the k parameter
    real get_k(real Ft, real Bt){
        return (sqrt(Ft^2*(4*Bt+Ft^2))+2*Bt+Ft^2)/(2*Bt);
    }

    //Compute the theta parameter
    real get_theta(real Ft, real Bt){
        return (sqrt(Ft^2*(4*Bt+Ft^2))-Ft^2)/(2*Ft);
    }

    //Compute the fixed term in the gamma function
    real get_gamma_term(real At, real k, real theta){
        return At/(exp(1-k)*((k-1)*theta)^(k-1));
    }

    //Compute the gamma function
    real gamma(real gamma_term, real k, real theta, real freq){
        return gamma_term*freq^(k-1)*exp(-freq/theta);
    }
}

