functions{
  matrix delete_row_col(matrix a, int n) {
    int N;
    matrix[rows(a) - 1, cols(a) - 1] result;
    N = rows(a);
    for (i in 1:(n-1)) {
      for (j in 1:(n-1))
        result[i,j] = a[i,j];
      for (j in (n+1):N)
        result[i,j-1] = a[i,j];
    }
    for (i in (n+1):N) {
      for (j in 1:(n-1))
        result[i-1,j] = a[i,j];
      for (j in (n+1):N)
        result[i-1,j-1] = a[i,j];
    }
    return result;
  }
  vector delete_row(vector a, int n) {
    int N;
    int k;
    vector[rows(a) - 1] result;
    N = rows(a);
    k = 1;
    for (i in 1:N){
      if(i != n){
        result[k] = a[i];
        k = k + 1;
      }
    }
    return result;
  }

  vector calculate_prob(vector c) {
    int K;
    vector[rows(c)+1] p;
    vector[rows(c)] c_sorted;

    K = rows(c)+1;

    c_sorted = sort_asc(c);
    p[1] = Phi(c_sorted[1]);
    for(k in 2:(K-1)){
      p[k] = Phi(c_sorted[k]) - Phi(c_sorted[k-1]);
    }
    p[K] = 1 - sum(p[1:(K-1)]);

    return(p);

  }
}
data{
  // # of observation
  int<lower=0> N;
  // # of scales of questionnaire
  int<lower=0> K;
  // # of questionnaires
  int<lower=0> S;

  // Data
  int<lower=0> X[N,S];

  // parameters of priors
  real<lower=0> nu_lambda;
  matrix[2,2] Lambda_bar;

}
transformed data{
  vector[K] zero;
  matrix[K,K] I;

  zero = rep_vector(0, K);
  I = diag_matrix(rep_vector(1, K));
}
parameters{

  vector<lower=-5, upper=5>[S] mu;
  vector[S] z[N];
  real<lower=-5, upper=5> tau[N];
  real<lower=0, upper=5> sigma[N];

  cov_matrix[S] Sigma;
  cov_matrix[2] Lambda;
  real<lower=-0.2, upper=0.2> e;
}
transformed parameters{

  simplex[K] p[N,S];
  vector[K-1] c;

  vector[S] c_nk;
  vector[K-1] c_sk[S];
  vector[2] phi;
  matrix[S,S] L;
  matrix[S,S] inv_L;
  vector[2] tau_lsigma[N];
  real a;
  real b;

  L = cholesky_decompose(Sigma);
  inv_L = inverse(L);

  phi[1] = 0;
  phi[2] = Lambda[2,2];

  for(i in 1:N){

    tau_lsigma[i][1] = tau[i];
    tau_lsigma[i][2] = log(sigma[i]);

  }

  // the answer of the simultanious equations bellow
  // CS3.6, CS3.7

  a = 2.157*e - 0.019*sqrt(-138688.0*e^2 - 29040.0*e + 24495.0) + 3.074;

  b = -6.765*e + 0.004*sqrt(-138688.0*e^2 - 29040.0*e + 24495.0) + 0.485;

  // CS3.7
  for(k in 1:(K-1)){
    c[k] = a + b*k + e*k^2;
  }
  c = sort_asc(c);

  for(n in 1:N){
    for(k in 1:(K-1)){
      c_nk = -inv_L*(mu + tau[n] - c[k])/sigma[n];
      for(s in 1:S){
        c_sk[s, k] = c_nk[s];
      }
    }
    for(s in 1:S){
      p[n, s] = calculate_prob(c_sk[s]);

    }
  }
}
model{
  e ~ uniform(-0.2, 0.2);
  Sigma ~ inv_wishart(K+3, (K+3)*I);
  Lambda ~ inv_wishart(nu_lambda, (nu_lambda-2-1)*Lambda_bar);
  z ~ multi_normal(zero, Sigma);

  for(n in 1:N){
    target += multi_normal_lpdf(tau_lsigma[n] | phi, Lambda);

    for(k in 1:K){
      X[n, k] ~ categorical(to_vector(p[n, k]));
    }
  }
}

