matrix sdpcorr2cov(matrix mat,int chol){ //converts from lower pcor and diag sd to chol or cov matrix
int ndim;
matrix[rows(mat),cols(mat)] mscale;
matrix[rows(mat),cols(mat)] mcholcor;
matrix[rows(mat),cols(mat)] out;
