for(rowi in coli:ndim){
if(rowi > coli){
mcholcor[rowi,coli] =  mat[rowi,coli];
mcholcor[coli,rowi] = 0;
}
}
}
for(rowi in 2:ndim){
mcholcor[rowi,rowi]<-sqrt(fabs(1-sum(vecpower(mcholcor[rowi,1:(rowi-1)],2))));
}
